// Probe the v3 lock primitive: a kernel lock (flock) on an open file
// description that the Node process owns. A short helper locks the INHERITED
// description and exits (util-linux `flock` stands in for the planned Rust
// internal route); the lock stays with Node's fd. Release = close(fd).
// Holder death = the kernel drops it. Borrow = the child inherits the same
// description at spawn (no spawn->bind window). Temp dirs only.
// Run: node probe-kernel-lock.mjs
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { spawn, spawnSync, execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const sleepMs = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(5); } };

/** Lock the description behind `fd` (non-blocking unless wait). */
export function lockFd(fd, { wait = false, timeoutMs = 5000 } = {}) {
  const r = spawnSync('flock', wait ? ['3'] : ['-n', '3'], { stdio: ['ignore', 'ignore', 'pipe', fd], timeout: timeoutMs, killSignal: 'SIGKILL' });
  return r.status === 0 ? 'acquired' : r.signal ? 'timeout' : 'held';
}
const strangerCanLock = (file) => spawnSync('flock', ['-n', file, 'true']).status === 0;

const role = process.argv[2];
if (role === 'stress-worker') {
  const [file, csDir, iters] = [process.argv[3], process.argv[4], Number(process.argv[5])];
  let violations = 0, acquired = 0;
  for (let i = 0; i < iters; i++) {
    const fd = fs.openSync(file, 'r+');
    if (lockFd(fd, { wait: true, timeoutMs: 8000 }) !== 'acquired') { fs.closeSync(fd); fs.writeFileSync(path.join(csDir, `..`, `stuck-${process.pid}`), ''); process.exit(2); }
    acquired++;
    const others = fs.readdirSync(csDir).filter((n) => n !== `${process.pid}`);
    // A witness left by a killed holder is retired by the killer before the kill completes.
    if (others.length) violations++;
    fs.writeFileSync(path.join(csDir, `${process.pid}`), '');
    sleepMs(Math.floor(Math.random() * 3));
    fs.rmSync(path.join(csDir, `${process.pid}`), { force: true });
    fs.closeSync(fd);
  }
  fs.writeFileSync(path.join(csDir, '..', `done-${process.pid}.json`), JSON.stringify({ acquired, violations }));
  process.exit(0);
}
if (role === 'holder') {
  const fd = fs.openSync(process.argv[3], 'r+');
  lockFd(fd); fs.writeFileSync(process.argv[4], ''); sleepMs(60000);
}
if (role === 'owner-spawns-git') {
  // Acquire, spawn git commit with the description at fd 3, then wait to be killed.
  const [file, repo, out] = process.argv.slice(3);
  const fd = fs.openSync(file, 'r+');
  if (lockFd(fd) !== 'acquired') throw new Error('owner: not acquired');
  const st = fs.fstatSync(fd);
  const git = spawn('git', ['-C', repo, 'commit', '-q', '-m', 'probe', '--', 'f.txt'], { stdio: ['ignore', 'ignore', 'inherit', fd], env: { ...process.env, FGOS_LOCK_FD: '3', EXPECT_DEVINO: `${st.dev}:${st.ino}`, PROBE_OUT: out }, detached: true });
  fs.writeFileSync(path.join(out, 'git-pid'), String(git.pid));
  sleepMs(60000);
}

if (!role) {
  const report = [];
  const root = fs.mkdtempSync(path.join(HERE, 'run-kl-'));
  const file = path.join(root, 'main.lock'); fs.writeFileSync(file, '');

  { // 1. Node holds after the helper exits; release = close
    const fd = fs.openSync(file, 'r+');
    const a = lockFd(fd);
    const strangerWhileHeld = strangerCanLock(file);
    fs.closeSync(fd);
    report.push({ case: 'node holds the lock after the helper exits; close releases', helper: a, strangerWhileHeld, strangerAfterClose: strangerCanLock(file) });
  }
  { // 2. two transactions in one process conflict (no re-entry by pid)
    const f1 = fs.openSync(file, 'r+'); const f2 = fs.openSync(file, 'r+');
    const r1 = lockFd(f1); const r2 = lockFd(f2); fs.closeSync(f1); const r3 = lockFd(f2); fs.closeSync(f2);
    report.push({ case: 'same process, two transactions (two descriptions)', first: r1, secondWhileFirstHeld: r2, secondAfterFirstClosed: r3 });
  }
  { // 3. holder SIGKILL releases
    const flag = path.join(root, 'held');
    const h = spawn(process.execPath, [ME, 'holder', file, flag], { stdio: 'inherit' });
    waitFile(flag);
    const before = strangerCanLock(file);
    h.kill('SIGKILL'); await new Promise((r) => h.on('exit', r));
    report.push({ case: 'holder SIGKILL', strangerBeforeKill: before, strangerAfterKill: strangerCanLock(file) });
  }
  { // 4. helper timeout (B8): kill + reap the helper, close our fd -> definitely not held by us
    const blockerFlag = path.join(root, 'blocker');
    const b = spawn(process.execPath, [ME, 'holder', file, blockerFlag], { stdio: 'inherit' });
    waitFile(blockerFlag);
    const fd = fs.openSync(file, 'r+');
    const t0 = Date.now(); const r = lockFd(fd, { wait: true, timeoutMs: 300 }); const ms = Date.now() - t0;
    fs.closeSync(fd); // outcome after a timeout is never "pending": we close, so we hold nothing
    b.kill('SIGKILL'); await new Promise((res) => b.on('exit', res));
    report.push({ case: 'helper timeout -> SIGKILL + reap (spawnSync) -> close', result: r, returnedAfterMs: ms, freeAfterBlockerDied: strangerCanLock(file) });
  }
  { // 5. borrow through a real git pre-commit hook; owner SIGKILLed right after spawn
    const repo = path.join(root, 'repo'); const out = path.join(root, 'git-out'); fs.mkdirSync(out);
    execFileSync('git', ['init', '-q', repo]);
    execFileSync('git', ['-C', repo, 'config', 'user.email', 'p@x']); execFileSync('git', ['-C', repo, 'config', 'user.name', 'p']);
    fs.writeFileSync(path.join(repo, 'f.txt'), 'x'); execFileSync('git', ['-C', repo, 'add', 'f.txt']);
    const hook = path.join(repo, '.git', 'hooks', 'pre-commit');
    fs.writeFileSync(hook, `#!/bin/sh
devino=$(stat -L -c %d:%i /proc/self/fd/3 2>/dev/null)
if [ "$devino" = "$EXPECT_DEVINO" ] && flock -n 3; then echo borrower > "$PROBE_OUT/hook"; else echo refused > "$PROBE_OUT/hook"; exit 1; fi
touch "$PROBE_OUT/hook-waiting"
while [ ! -f "$PROBE_OUT/hook-go" ]; do sleep 0.05; done
`); fs.chmodSync(hook, 0o755);
    const owner = spawn(process.execPath, [ME, 'owner-spawns-git', file, repo, out], { stdio: 'inherit' });
    waitFile(path.join(out, 'git-pid'));
    owner.kill('SIGKILL'); await new Promise((r) => owner.on('exit', r)); // owner dies before anything else
    waitFile(path.join(out, 'hook-waiting'));
    const contenderWhileGitRuns = strangerCanLock(file);
    const st = fs.statSync(file);
    // a sibling with the same env but its own (new) description of the file
    const sib = spawnSync('sh', ['-c', `devino=$(stat -L -c %d:%i /proc/self/fd/3); if [ "$devino" = "${st.dev}:${st.ino}" ] && flock -n 3; then echo borrower; else echo refused; fi`], { stdio: ['ignore', 'pipe', 'inherit', fs.openSync(file, 'r')], env: { ...process.env, FGOS_LOCK_FD: '3' } }).stdout.toString().trim();
    fs.writeFileSync(path.join(out, 'hook-go'), '');
    const gitPid = Number(fs.readFileSync(path.join(out, 'git-pid'), 'utf8'));
    for (let i = 0; i < 200; i++) { try { process.kill(gitPid, 0); sleepMs(20); } catch { break; } }
    const committed = execFileSync('git', ['-C', repo, 'log', '--oneline']).toString().trim().length > 0;
    report.push({ case: 'borrow through real git hook; owner SIGKILL right after spawn', hookBorrowCheck: fs.readFileSync(path.join(out, 'hook'), 'utf8').trim(), contenderWhileGitRuns, siblingWithEnvButOwnDescription: sib, gitCommitted: committed, contenderAfterGitExit: strangerCanLock(file) });
  }
  { // 6. stress with SIGKILLs of holders
    const sfile = path.join(root, 'stress.lock'); fs.writeFileSync(sfile, '');
    const csDir = path.join(root, 'cs'); fs.mkdirSync(csDir);
    const live = new Set();
    let kills = 0, spawned = 0;
    const start = (n) => { const k = spawn(process.execPath, [ME, 'stress-worker', sfile, csDir, String(n)], { stdio: 'inherit' }); spawned++; live.add(k); k.on('exit', (code, sig) => { live.delete(k); if (sig === 'SIGKILL') start(30); }); };
    for (let i = 0; i < 8; i++) start(100);
    const killer = setInterval(() => {
      const inside = fs.readdirSync(csDir);
      if (!inside.length || kills >= 25) return;
      const pid = Number(inside[0]);
      try { process.kill(pid, 'SIGSTOP'); fs.rmSync(path.join(csDir, inside[0]), { force: true }); process.kill(pid, 'SIGKILL'); kills++; } catch {}
    }, 60);
    const t0 = Date.now();
    while (live.size || kills < 25 && Date.now() - t0 < 1000) { await new Promise((r) => setTimeout(r, 50)); if (!live.size) break; }
    clearInterval(killer);
    const dones = fs.readdirSync(root).filter((n) => n.startsWith('done-')).map((n) => JSON.parse(fs.readFileSync(path.join(root, n), 'utf8')));
    report.push({ case: 'stress 8 procs x 100 (+30 per replacement), holders SIGKILLed inside the critical section and replaced', kills, workersSpawned: spawned, survivorsFinished: dones.length, acquisitions: dones.reduce((a, d) => a + d.acquired, 0), csViolations: dones.reduce((a, d) => a + d.violations, 0), stuck: fs.readdirSync(root).filter((n) => n.startsWith('stuck-')).length, elapsedMs: Date.now() - t0 });
  }
  { // 7. cost of acquire through a helper exec (util-linux flock as the stand-in)
    const ts = [];
    for (let i = 0; i < 300; i++) { const fd = fs.openSync(file, 'r+'); const t0 = process.hrtime.bigint(); lockFd(fd); ts.push(Number(process.hrtime.bigint() - t0) / 1e6); fs.closeSync(fd); }
    ts.sort((a, b) => a - b); const q = (p) => +ts[Math.floor(p * (ts.length - 1))].toFixed(2);
    report.push({ case: 'acquire cost via helper exec (ms)', n: 300, p50: q(0.5), p95: q(0.95), p99: q(0.99) });
  }
  fs.writeFileSync(path.join(HERE, 'probe-kernel-lock-results.json'), JSON.stringify({ node: process.version, cpus: os.cpus().length, load: os.loadavg()[0], report }, null, 1));
  for (const r of report) console.log(JSON.stringify(r));
}

files.probe-hot-reclaim.mjs:
// Probe the interim Node hot-path mutex (events.lock): keep today's link/unlink
// fast path, but reclaim a dead holder's record only while holding a kernel
// "reclaim" lock (flock via helper exec, util-linux stand-in). Record = {pid,
// startTime, boot}. A1 schedule: R1 judged X dead and re-read it, then pauses
// right before unlink; R2 reclaims meanwhile. Run: node probe-hot-reclaim.mjs
import fs from 'node:fs';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { startTimeOf, currentBoot, judgeOwner, self } from './era-ledger.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const sleepMs = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(2); } };

function lockFd(fd) { return spawnSync('flock', ['-n', '3'], { stdio: ['ignore', 'ignore', 'ignore', fd] }).status === 0; }

/** One attempt: 'acquired' | 'held'. */
export function hotTryAcquire(lockPath, { reclaimLock = true, beforeUnlink } = {}) {
  const tmp = `${lockPath}.tmp-${process.pid}-${Math.random().toString(36).slice(2)}`;
  fs.writeFileSync(tmp, JSON.stringify({ ...self(), boot: currentBoot() }));
  try { fs.linkSync(tmp, lockPath); return 'acquired'; } catch (e) { if (e.code !== 'EEXIST') throw e; } finally { fs.unlinkSync(tmp); }
  let raw; try { raw = fs.readFileSync(lockPath, 'utf8'); } catch (e) { if (e.code === 'ENOENT') return 'retry'; throw e; }
  let rec = null; try { rec = JSON.parse(raw); } catch {}
  const dead = (r) => r && (r.boot !== currentBoot() || judgeOwner(r) === 'dead');
  if (!dead(rec)) return 'held'; // alive, unknown or unreadable: never reclaimed
  let rfd = null;
  if (reclaimLock) { rfd = fs.openSync(`${lockPath}.reclaim`, fs.constants.O_RDWR | fs.constants.O_CREAT); if (!lockFd(rfd)) { fs.closeSync(rfd); return 'held'; } }
  try {
    let cur; try { cur = fs.readFileSync(lockPath, 'utf8'); } catch (e) { if (e.code === 'ENOENT') return 'retry'; throw e; }
    if (cur !== raw) return 'retry';
    beforeUnlink?.();
    fs.unlinkSync(lockPath);
    return 'retry';
  } finally { if (rfd !== null) fs.closeSync(rfd); }
}
export function hotAcquire(lockPath, opts = {}) {
  for (let i = 0; i < 100000; i++) { const r = hotTryAcquire(lockPath, opts); if (r === 'acquired') return true; sleepMs(r === 'retry' ? 0 : 1); }
  return false;
}

const role = process.argv[2];
if (role === 'deadholder') { const [lp] = process.argv.slice(3); fs.writeFileSync(lp, JSON.stringify({ ...self(), boot: currentBoot() })); process.exit(0); }
if (role === 'R1') {
  const [lp, work, useLock] = process.argv.slice(3);
  const opts = { reclaimLock: useLock === '1', beforeUnlink: () => { if (!fs.existsSync(path.join(work, 'R1-go'))) { fs.writeFileSync(path.join(work, 'R1-paused'), ''); waitFile(path.join(work, 'R1-go')); } } };
  let r; do { r = hotTryAcquire(lp, opts); } while (r === 'retry');
  const others = r === 'acquired' ? fs.readdirSync(path.join(work, 'cs')).length : null;
  if (r === 'acquired') fs.writeFileSync(path.join(work, 'cs', 'R1'), '');
  fs.writeFileSync(path.join(work, 'R1.json'), JSON.stringify({ result: r, othersInsideOnEntry: others }));
  process.exit(0);
}
if (role === 'R2') {
  const [lp, work, useLock] = process.argv.slice(3);
  const ok = hotAcquire(lp, { reclaimLock: useLock === '1' });
  fs.writeFileSync(path.join(work, 'cs', 'R2'), '');
  fs.writeFileSync(path.join(work, 'R2-inside'), String(ok));
  waitFile(path.join(work, 'R2-leave'));
  fs.rmSync(path.join(work, 'cs', 'R2')); fs.unlinkSync(lp); process.exit(0);
}
if (role === 'stress') {
  const [lp, work, iters, useLock] = process.argv.slice(3);
  let v = 0, n = 0;
  for (let i = 0; i < Number(iters); i++) {
    hotAcquire(lp, { reclaimLock: useLock === '1', beforeUnlink: () => { if (Math.random() < 0.2) sleepMs(3); } }); n++;
    if (fs.readdirSync(path.join(work, 'cs')).filter((x) => x !== String(process.pid)).length) v++;
    fs.writeFileSync(path.join(work, 'cs', String(process.pid)), '');
    sleepMs(Math.floor(Math.random() * 2));
    fs.rmSync(path.join(work, 'cs', String(process.pid)), { force: true });
    fs.unlinkSync(lp);
  }
  fs.writeFileSync(path.join(work, `done-${process.pid}.json`), JSON.stringify({ n, v }));
  process.exit(0);
}

if (!role) {
  const report = [];
  const done = (cp) => new Promise((r) => cp.on('exit', r));
  for (const useLock of ['0', '1']) {
    const work = fs.mkdtempSync(path.join(HERE, `run-hot-a1-${useLock}-`)); fs.mkdirSync(path.join(work, 'cs'));
    const lp = path.join(work, 'events.lock');
    await done(spawn(process.execPath, [ME, 'deadholder', lp], { stdio: 'inherit' })); // X: holder died inside
    const R1 = spawn(process.execPath, [ME, 'R1', lp, work, useLock], { stdio: 'inherit' });
    waitFile(path.join(work, 'R1-paused'));
    const R2 = spawn(process.execPath, [ME, 'R2', lp, work, useLock], { stdio: 'inherit' });
    const t0 = Date.now(); while (!fs.existsSync(path.join(work, 'R2-inside')) && Date.now() - t0 < 1500) sleepMs(5);
    const r2InsideWhileR1Paused = fs.existsSync(path.join(work, 'R2-inside'));
    fs.writeFileSync(path.join(work, 'R1-go'), '');
    await done(R1);
    fs.writeFileSync(path.join(work, 'R2-leave'), '');
    if (!r2InsideWhileR1Paused) { /* R2 may enter only after R1 left */ }
    await new Promise((r) => setTimeout(r, 300));
    const r1 = JSON.parse(fs.readFileSync(path.join(work, 'R1.json'), 'utf8'));
    report.push({ case: `A1 schedule on events.lock, reclaim under kernel lock = ${useLock === '1'}`, r2EnteredWhileR1PausedBeforeUnlink: r2InsideWhileR1Paused, R1: r1, twoHolders: r1.result === 'acquired' && r1.othersInsideOnEntry > 0 });
    R2.kill('SIGKILL');
  }
  for (const useLock of ['0', '1']) {
    const work = fs.mkdtempSync(path.join(HERE, `run-hot-stress-${useLock}-`)); fs.mkdirSync(path.join(work, 'cs'));
    const lp = path.join(work, 'events.lock');
    const kids = [];
    let kills = 0;
    const startKid = (n) => { const k = spawn(process.execPath, [ME, 'stress', lp, work, String(n), useLock], { stdio: 'inherit' }); kids.push(k); return k; };
    for (let i = 0; i < 8; i++) startKid(150);
    const killer = setInterval(() => { // kill a holder inside the CS now and then, replace it
      if (kills >= 20) return; const inside = fs.readdirSync(path.join(work, 'cs')); if (!inside.length) return;
      const pid = Number(inside[0]); try { process.kill(pid, 'SIGSTOP'); fs.rmSync(path.join(work, 'cs', inside[0]), { force: true }); process.kill(pid, 'SIGKILL'); kills++; startKid(40); } catch {}
    }, 50);
    const t0 = Date.now();
    while (kids.some((k) => k.exitCode === null && k.signalCode === null) && Date.now() - t0 < 60000) await new Promise((r) => setTimeout(r, 50));
    clearInterval(killer);
    const ds = fs.readdirSync(work).filter((f) => f.startsWith('done-')).map((f) => JSON.parse(fs.readFileSync(path.join(work, f), 'utf8')));
    report.push({ case: `stress 8 procs, ${kills} holders SIGKILLed in CS, reclaim under kernel lock = ${useLock === '1'}`, acquisitions: ds.reduce((a, d) => a + d.n, 0), csViolations: ds.reduce((a, d) => a + d.v, 0), finishedWorkers: ds.length, elapsedMs: Date.now() - t0 });
  }
  fs.writeFileSync(path.join(HERE, 'probe-hot-reclaim-results.json'), JSON.stringify(report, null, 1));
  for (const r of report) console.log(JSON.stringify(r));
}

files.probe-tombstone.mjs:
// Probe B2 (physical launch floor): a directory "tombstone" at a v1 lock path.
// Runs the REAL v1 lock code (main HEAD, and the W1' branch copy) against it:
// acquire, inspect, release, releaseIfOwn, forceReclaim. Every call must fail
// closed (throw or report held/ambiguous) and leave the tombstone in place.
// Run: node probe-tombstone.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const HERE = path.dirname(fileURLToPath(import.meta.url));
const variants = {
  'main-HEAD': '/home/vantt/projects/forgentX/src/runner/main-checkout-lock.mjs',
  'W1-branch': path.join(HERE, 'v1-w1/src/runner/main-checkout-lock.mjs'),
};
const out = [];
for (const [name, mod] of Object.entries(variants)) {
  const m = await import(mod);
  const dir = fs.mkdtempSync(path.join(HERE, `run-tomb-${name}-`));
  const lockPath = path.join(dir, 'main-checkout.lock');
  fs.mkdirSync(lockPath); fs.writeFileSync(path.join(lockPath, 'TOMBSTONE'), JSON.stringify({ v: 3, movedTo: 'runtime/locks/main-checkout/' }));
  const call = (label, fn) => { try { const r = fn(); out.push({ variant: name, call: label, returned: r?.status ?? r }); } catch (e) { out.push({ variant: name, call: label, threw: e.code || e.message }); } };
  call('acquire(pid)', () => m.acquireMainCheckoutLock(dir, { identity: process.pid, ttlMs: 1000 }));
  call('acquire(session string)', () => m.acquireMainCheckoutLock(dir, { identity: 'sess-x', ttlMs: 1000 }));
  if (m.inspectMainCheckoutLock) call('inspect', () => m.inspectMainCheckoutLock(dir));
  call('release', () => m.releaseMainCheckoutLock(dir));
  call('releaseIfOwn', () => m.releaseMainCheckoutLockIfOwn(dir, process.pid));
  call('forceReclaimAmbiguous', () => m.forceReclaimAmbiguousLock(dir));
  out.push({ variant: name, tombstoneStillThere: fs.statSync(lockPath).isDirectory() && fs.existsSync(path.join(lockPath, 'TOMBSTONE')) });
}
fs.writeFileSync(path.join(HERE, 'probe-tombstone-results.json'), JSON.stringify(out, null, 1));
for (const o of out) console.log(JSON.stringify(o));

