// P4: controller-crash simulation of the supervisor protocol (T8 schedules).
// Every case SIGKILLs the controller right after it launched the supervisor.
import fs from 'node:fs';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = fs.mkdtempSync(path.join(here, 'p4-'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const waitFile = async (p, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(p)) { if (Date.now() > end) throw new Error(`timeout ${p}`); await sleep(10); } };
const lockFree = (d) => spawnSync('flock', ['-n', path.join(d, 'attempt.lock'), 'true']).status === 0;
const readJ = (p) => (fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null);
const adopt = (d) => JSON.parse(spawnSync(process.execPath, [path.join(here, 'p4-adopt.mjs'), d], { encoding: 'utf8' }).stdout);
const alive = (pid) => { try { process.kill(pid, 0); return !fs.readFileSync(`/proc/${pid}/stat`, 'utf8').split(') ')[1].startsWith('Z'); } catch { return false; } };

async function launch(name, c) {
  const d = path.join(root, name);
  const ctl = spawn(process.execPath, [path.join(here, 'p4-controller.mjs'), d, JSON.stringify(c)], { stdio: 'ignore' });
  await waitFile(path.join(d, 'controller-ready'));
  ctl.kill('SIGKILL');
