// P5a: stress the kernel-lock mutex from Node: 8 processes x 120 acquisitions,
// acquire = open + helper flock on the inherited description (blocking, 5 s cap),
// release = close. A killer SIGKILLs random holders INSIDE the critical section.
// Witness: another process's witness file in the CS directory = violation. A
// killed holder is SIGSTOPped, its witness retired, then SIGKILLed (exact). Stuck = a
// worker that never gets the lock after holders died.
// P5b: the B1 schedule against the run-control ledger WITHOUT GC (production
// publishNextGeneration): the paused contender's stale link hits EEXIST and it
// re-decides; no hole can exist, so no post-check is needed.
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { publishNextGeneration, publishMarkerOnce, currentGeneration } from '/home/vantt/projects/forgentX/src/runner/dispatch/run-lock.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = fs.mkdtempSync(path.join(here, 'p5-'));
const lockFile = path.join(root, 'lock');
const cs = path.join(root, 'cs');
fs.mkdirSync(cs);
fs.writeFileSync(lockFile, '');
const W = 8, N = 120;
const WORKER = `
const fs=require('fs'),path=require('path');const {spawnSync}=require('child_process');
const [lock,cs,n,out]=process.argv.slice(1);let v=0,a=0,t=0;
const liveOthers=()=>fs.readdirSync(cs).filter(f=>!f.startsWith(process.pid+'-')).length;
for(let i=0;i<+n;i++){
  const fd=fs.openSync(lock,'r');
  const r=spawnSync('flock',['-w','5','3'],{stdio:['ignore','ignore','ignore',fd]});
  if(r.status!==0){t++;fs.closeSync(fd);continue;}
  a++;const tag=path.join(cs,process.pid+'-'+i);fs.writeFileSync(tag,'');
  if(liveOthers()>0)v++;
  const e=Date.now()+Math.random()*3;while(Date.now()<e){}
  if(liveOthers()>0)v++;
  fs.unlinkSync(tag);fs.closeSync(fd);
  fs.writeFileSync(out,JSON.stringify({a,v,t}));
}
fs.writeFileSync(out,JSON.stringify({a,v,t,done:true}));`;

const procs = new Map();
let spawned = 0;
function start(i) {
  const out = path.join(root, `w${i}-${spawned++}.json`);
  const p = spawn(process.execPath, ['-e', WORKER, lockFile, cs, String(N), out], { stdio: 'ignore' });
  procs.set(p.pid, { p, i, out });
  p.on('exit', () => procs.delete(p.pid));
}
for (let i = 0; i < W; i++) start(i);
let kills = 0, killsInsideCs = 0;
const t0 = Date.now();
while (procs.size > 0 && Date.now() - t0 < 120000) {
  await new Promise((r) => setTimeout(r, 40 + Math.random() * 60));
  const inside = fs.readdirSync(cs);
  if (inside.length && kills < 25) {
    const pid = Number(inside[0].split('-')[0]);
    const entry = procs.get(pid);
    if (entry) {
      // Exact witness: freeze the victim (it runs no more user code but still
      // holds the lock), retire its witness file, then kill it.
      entry.p.kill('SIGSTOP');
      await new Promise((r) => setTimeout(r, 5));
      for (const f of fs.readdirSync(cs)) if (f.startsWith(`${pid}-`)) { try { fs.renameSync(path.join(cs, f), path.join(root, `retired-${f}`)); } catch {} }
      entry.p.kill('SIGKILL'); kills++; killsInsideCs++;
      await new Promise((r) => entry.p.on('exit', r));
      start(entry.i);
    }
  }
}
const outs = fs.readdirSync(root).filter((f) => /^w\d+-\d+\.json$/.test(f)).map((f) => { try { return JSON.parse(fs.readFileSync(path.join(root, f), 'utf8')); } catch { return { a: 0, v: 0, t: 0 }; } });
const stress = {
  case: `kernel-lock stress ${W} procs x ${N}, ${kills} SIGKILLs of holders inside the CS`,
  acquisitions: outs.reduce((s, o) => s + o.a, 0),
  csViolations: outs.reduce((s, o) => s + o.v, 0),
  timeoutsWaiting5s: outs.reduce((s, o) => s + o.t, 0),
  elapsedMs: Date.now() - t0,
  allWorkersFinished: procs.size === 0,
};

// P5b: B1 schedule, ledger without GC
const gens = path.join(root, 'control', 'generations');
const rel = path.join(root, 'control', 'releases');
const g1 = publishNextGeneration(gens, () => ({ record: { holder: 'A1' } }));
publishMarkerOnce(path.join(rel, '1.release'), {});
// C decides "1 released -> I publish 2" and is paused before link: emulate by
// capturing its decision, letting A(2), B(3) proceed, then retrying C's link.
let cTried = 0;
const a2 = publishNextGeneration(gens, () => ({ record: { holder: 'A2' } }));
const b3 = publishNextGeneration(gens, () => ({ record: { holder: 'B3' } }));
// No GC: generations 1 and 2 still exist. C resumes with its stale target 2.
let cOutcome;
try { fs.linkSync(path.join(gens, '0000000003.json'), path.join(gens, '0000000002.json')); cOutcome = 'linked'; } catch (e) { cOutcome = e.code; }
const cRedecide = publishNextGeneration(gens, ({ current }) => { cTried++; return current.record.holder === 'B3' ? { stop: true, status: 'held', epoch: current.epoch } : { record: { holder: 'C' } }; });
const ledger = { case: 'B1 schedule on the run-control ledger without GC', staleLinkTo2: cOutcome, redecidedAgainst: currentGeneration(gens).epoch, cOutcome: cRedecide.status, generationsOnDisk: fs.readdirSync(gens).length, epochs: [g1.epoch, a2.epoch, b3.epoch] };

const out = { root, results: [stress, ledger] };
fs.writeFileSync(path.join(here, 'p5-results.json'), JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

