// P6 (B2): round 2's schedule against the quiescent raise rule. A v1 holder
// (production acquireMainCheckoutLock, TTL 60 ms) is paused past its TTL inside
// its critical section. Round-2 raiser (takes v1 by TTL, raises marker) vs v3
// raiser rule: refuse unless (a) no other fgOS process is running for this
// workspace (cmdline scan) and (b) the v1 lock file does not exist at all; the
// raiser then creates it exclusively (link) and holds it while writing the marker.
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { acquireMainCheckoutLock, ACQUIRED } from '/home/vantt/projects/forgentX/src/runner/main-checkout-lock.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = fs.mkdtempSync(path.join(here, 'p6-'));
const fgos = path.join(root, '.fgos');
fs.mkdirSync(fgos);
const TAG = `fgos-p6-workspace-${process.pid}`;
const v1 = path.join(fgos, 'main-checkout.lock');
// the holder: a process that "runs fgOS for this workspace" (TAG in argv), holds v1, then is paused
const holder = spawn(process.execPath, ['--input-type=module', '-e', `
  const { acquireMainCheckoutLock } = await import('/home/vantt/projects/forgentX/src/runner/main-checkout-lock.mjs');
  const r = acquireMainCheckoutLock(${JSON.stringify(fgos)}, { identity: process.pid, ttlMs: 60 });
  (await import('node:fs')).default.writeFileSync(${JSON.stringify(path.join(root, 'held'))}, r.status);
  setInterval(()=>{}, 1000);`, TAG], { stdio: 'ignore' });
