holder.kill('SIGSTOP');                       // paused inside its critical section
await new Promise((r) => setTimeout(r, 100)); // past its TTL

function otherWorkspaceProcesses() {
  return fs.readdirSync('/proc').filter((p) => /^\d+$/.test(p) && Number(p) !== process.pid).filter((p) => {
    try { return fs.readFileSync(`/proc/${p}/cmdline`, 'utf8').includes(TAG); } catch { return false; }
  });
}
// round-2 raiser: acquire v1 (TTL takeover allowed by production v1), raise
const r2 = acquireMainCheckoutLock(fgos, { identity: process.pid + 1, ttlMs: 60 });
const round2 = { raiserV1Status: r2.status, wouldRaiseWhileHolderInCs: r2.status === ACQUIRED };
if (r2.status === ACQUIRED) r2.release?.();

// v3 quiescent raise
const others = otherWorkspaceProcesses();
const v1Exists = fs.existsSync(v1);
const v3 = { otherFgosProcesses: others.length, v1FilePresent: v1Exists, decision: others.length === 0 && !v1Exists ? 'raise' : 'refuse' };

holder.kill('SIGKILL');
const out = { root, case: 'v1 holder paused past TTL inside its CS during upgrade', round2RaiserRule: round2, v3QuiescentRaiseRule: v3 };
