files.era-ledger.mjs:
// Model of the v3 holder-lock protocol ("era ledger"). Probe code, not an
// implementation. Writes only under the lockDir a probe passes in.
//
// Layout:
//   <lockDir>/current                 {"era": "<name>"}; created by link-if-absent,
//                                     replaced by rename only by the current holder
//   <lockDir>/eras/<era>/gen/<epoch>  one generation per acquire; NEVER deleted
//                                     while its era is reachable from `current`
//   <lockDir>/eras/<era>/rel/<epoch>  one-shot release marker
// Era name: <firstEpoch10>-<bootIdHex>-<rand>. The boot of every record in an
// era is the era's boot (no mtime anywhere).
//
// Acquire linearizes at a successful link of gen/<max+1> in era e, confirmed
// by a post-check that `current` still names e. GC = the holder moves the
// ledger to a new era (copy of its own record), swaps `current`, then deletes
// the old era. A stale contender can only link into an unreachable era (post
// check fails) or into a deleted one (ENOENT).
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export function currentBoot() {
  if (process.env.PROBE_BOOT_ID) return process.env.PROBE_BOOT_ID;
  try { return fs.readFileSync('/proc/sys/kernel/random/boot_id', 'utf8').trim().replace(/-/g, ''); } catch { return 'unknown'; }
}
export function startTimeOf(pid) {
  try {
    const s = fs.readFileSync(`/proc/${pid}/stat`, 'utf8');
    return s.slice(s.lastIndexOf(')') + 2).split(' ')[19] || null;
  } catch { return null; }
}
function kill0(pid) { try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; } }

/** alive | dead | unknown. Never reads mtime. */
export function judgeOwner(owner) {
  if (!owner || !Number.isInteger(owner.pid)) return 'unknown';
  if (!kill0(owner.pid)) return 'dead';
  const st = startTimeOf(owner.pid);
  if (st === null || !owner.startTime) return 'unknown';
  return st === owner.startTime ? 'alive' : 'dead';
}
export function self() { return { pid: process.pid, startTime: startTimeOf(process.pid) }; }

const pad = (n) => String(n).padStart(10, '0');
const GEN_RE = /^(\d{10})$/;
const eraBoot = (era) => era.split('-')[1];
const eraFirst = (era) => Number(era.split('-')[0]);

function readPointer(lockDir) {
  try { return JSON.parse(fs.readFileSync(path.join(lockDir, 'current'), 'utf8')).era; }
  catch (e) { if (e.code === 'ENOENT') return null; throw e; }
}
function writeFileFsync(p, content) {
  const fd = fs.openSync(p, 'w'); try { fs.writeSync(fd, content); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
}
function newEraName(firstEpoch) { return `${pad(firstEpoch)}-${currentBoot()}-${crypto.randomBytes(4).toString('hex')}`; }

function bootstrap(lockDir) {
  const era = newEraName(0);
  fs.mkdirSync(path.join(lockDir, 'eras', era, 'gen'), { recursive: true });
  fs.mkdirSync(path.join(lockDir, 'eras', era, 'rel'), { recursive: true });
  const tmp = path.join(lockDir, `.ptr-${process.pid}-${crypto.randomBytes(4).toString('hex')}`);
  writeFileFsync(tmp, JSON.stringify({ era }));
  try { fs.linkSync(tmp, path.join(lockDir, 'current')); }
  catch (e) { if (e.code !== 'EEXIST') throw e; fs.rmSync(path.join(lockDir, 'eras', era), { recursive: true, force: true }); }
  fs.unlinkSync(tmp);
}

/** Name-based max of a reachable era. Null for an era with no generations. */
function maxEpochByName(genDir) {
  const names = fs.readdirSync(genDir); // throws ENOENT when the era was deleted
  let max = null;
  for (const n of names) { const m = GEN_RE.exec(n); if (m && (max === null || Number(m[1]) > max)) max = Number(m[1]); }
  return max;
}

/**
 * One acquire attempt loop. Returns {status:'acquired', handle} or
 * {status:'held', reason}. Hooks let probes pause at the dangerous gaps.
 */
export function tryAcquire(lockDir, { owner = self(), compactEvery = 64, hooks = {}, stats = {}, extraHeld = null } = {}) {
  fs.mkdirSync(path.join(lockDir, 'eras'), { recursive: true });
  for (let loops = 0; loops < 10000; loops++) {
    let era = readPointer(lockDir);
    if (era === null) { bootstrap(lockDir); continue; }
    hooks.afterPointer?.({ era });
    const eraDir = path.join(lockDir, 'eras', era);
    let max;
    try { max = maxEpochByName(path.join(eraDir, 'gen')); }
    catch (e) { if (e.code === 'ENOENT') { stats.eraGone = (stats.eraGone || 0) + 1; continue; } throw e; }
    const bootDead = eraBoot(era) !== 'unknown' && eraBoot(era) !== currentBoot();
    if (max !== null && !bootDead) {
      let rec;
      try { rec = fs.readFileSync(path.join(eraDir, 'gen', pad(max)), 'utf8'); }
      catch (e) { if (e.code === 'ENOENT') { stats.eraGone = (stats.eraGone || 0) + 1; continue; } throw e; }
      let parsed = null; try { parsed = JSON.parse(rec); } catch {}
      if (parsed === null) return { status: 'held', reason: 'unknown-record' };
      const released = fs.existsSync(path.join(eraDir, 'rel', pad(max)));
      if (!released) {
        const verdict = judgeOwner(parsed.owner);
        if (verdict !== 'dead') return { status: 'held', reason: verdict, holder: parsed.owner };
        // Generation stays held while a bound borrower of it is alive.
        if (extraHeld?.(parsed)) return { status: 'held', reason: 'borrower-alive' };
      }
    }
    const next = (max ?? eraFirst(era)) + 1;
    hooks.beforeLink?.({ era, next });
    const token = crypto.randomUUID();
    const tmp = path.join(lockDir, `.tmp-${process.pid}-${crypto.randomBytes(4).toString('hex')}`);
    fs.writeFileSync(tmp, JSON.stringify({ v: 3, epoch: next, token, owner }));
    try { fs.linkSync(tmp, path.join(eraDir, 'gen', pad(next))); }
    catch (e) {
      fs.unlinkSync(tmp);
      if (e.code === 'EEXIST' || e.code === 'ENOENT') { stats.lostLink = (stats.lostLink || 0) + 1; continue; }
      throw e;
    }
    fs.unlinkSync(tmp);
    hooks.beforePostCheck?.({ era, next });
    if (process.env.PROBE_NO_POSTCHECK !== '1' && readPointer(lockDir) !== era) { stats.unreachableLink = (stats.unreachableLink || 0) + 1; continue; }
