}

/** Holder-only: move the ledger to a fresh era holding a copy of our record. */
function compact(handle, stats) {
  const { lockDir, era: oldEra, epoch } = handle;
  const era = newEraName(epoch);
  const eraDir = path.join(lockDir, 'eras', era);
  fs.mkdirSync(eraDir); // exclusive: a fresh, unique name
  fs.mkdirSync(path.join(eraDir, 'gen'));
  fs.mkdirSync(path.join(eraDir, 'rel'));
  fs.copyFileSync(path.join(lockDir, 'eras', oldEra, 'gen', pad(epoch)), path.join(eraDir, 'gen', pad(epoch)));
  const tmp = path.join(lockDir, `.ptr-${process.pid}-${crypto.randomBytes(4).toString('hex')}`);
  writeFileFsync(tmp, JSON.stringify({ era }));
  fs.renameSync(tmp, path.join(lockDir, 'current'));
  handle.era = era;
  stats.compactions = (stats.compactions || 0) + 1;
  // Delete every era other than the one we just made current.
  if (process.env.PROBE_KEEP_OLD_ERAS === '1') return;
  for (const name of fs.readdirSync(path.join(lockDir, 'eras'))) {
    if (name !== era) { try { fs.rmSync(path.join(lockDir, 'eras', name), { recursive: true, force: true }); } catch {} }
