// Probe B1 + B7 against the era-ledger model: paused contenders vs GC (era
// compaction), stress with aggressive compaction, boot-era death, corrupt
// record, mtime ignored. Run: node probe-era-ledger.mjs
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { tryAcquire, release, sleepMs } from './era-ledger.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(5); } };

// ---------- child roles ----------
const role = process.argv[2];
if (role) {
  const [lockDir, work] = [process.argv[3], process.argv[4]];
  const out = (o) => fs.writeFileSync(path.join(work, `${role}-${process.pid}.json`), JSON.stringify(o));
  const csEnter = (tag) => { const d = path.join(work, 'cs'); fs.mkdirSync(d, { recursive: true }); const others = fs.readdirSync(d).length; fs.writeFileSync(path.join(d, `${tag}-${process.pid}`), ''); return others; };
  const csLeave = (tag) => fs.rmSync(path.join(work, 'cs', `${tag}-${process.pid}`), { force: true });
  if (role === 'paused-contender') {
    // Decides, then waits at the barrier before link (the A1/B1 gap).
    const stats = {};
    const r = tryAcquire(lockDir, { compactEvery: 2, stats, hooks: { beforeLink: () => { fs.writeFileSync(path.join(work, 'C-decided'), ''); waitFile(path.join(work, 'C-go')); } } });
    const others = r.status === 'acquired' ? csEnter('C') : null;
    out({ status: r.status, reason: r.reason, epoch: r.handle?.epoch, othersInsideOnEntry: others, stats });
    if (r.status === 'acquired') { sleepMs(300); csLeave('C'); release(r.handle); }
    process.exit(0);
  }
  if (role === 'stale-pointer-contender') {
    // Reads `current`, then waits before reading the era (holder compacts and dies meanwhile).
    const r = tryAcquire(lockDir, { compactEvery: 64, hooks: { afterPointer: () => { if (!fs.existsSync(path.join(work, 'C-go'))) { fs.writeFileSync(path.join(work, 'C-read-pointer'), ''); waitFile(path.join(work, 'C-go')); } } } });
    const others = r.status === 'acquired' ? csEnter('C') : null;
    out({ status: r.status, reason: r.reason, era: r.handle?.era, epoch: r.handle?.epoch, othersInsideOnEntry: others });
    if (r.status === 'acquired') { sleepMs(200); csLeave('C'); release(r.handle); }
    process.exit(0);
  }
  if (role === 'cycler') {
    // Acquire/release a few times so compaction moves and deletes eras.
    const n = Number(process.argv[5]);
    for (let i = 0; i < n; i++) { let r; do { r = tryAcquire(lockDir, { compactEvery: 2 }); if (r.status !== 'acquired') sleepMs(2); } while (r.status !== 'acquired'); release(r.handle); }
    process.exit(0);
  }
