    let r; do { r = tryAcquire(lockDir, { compactEvery: 2 }); if (r.status !== 'acquired') sleepMs(2); } while (r.status !== 'acquired');
    const others = csEnter('D');
    fs.writeFileSync(path.join(work, 'D-inside'), JSON.stringify({ epoch: r.handle.epoch, others }));
    waitFile(path.join(work, 'D-leave'));
    csLeave('D'); release(r.handle); process.exit(0);
  }
  if (role === 'post-check-paused') {
