    const r = tryAcquire(lockDir, { compactEvery: 2, hooks: { beforePostCheck: () => { fs.writeFileSync(path.join(work, 'P-linked'), ''); waitFile(path.join(work, 'P-go')); } } });
    const others = r.status === 'acquired' ? csEnter('P') : null;
    out({ status: r.status, epoch: r.handle?.epoch, othersInsideOnEntry: others });
    if (r.status === 'acquired') { sleepMs(200); csLeave('P'); release(r.handle); }
    process.exit(0);
  }
  if (role === 'try-once') {
    const r = tryAcquire(lockDir, { compactEvery: 2 });
    out({ status: r.status, reason: r.reason, epoch: r.handle?.epoch });
    if (r.status === 'acquired') release(r.handle);
    process.exit(0);
