    for (let i = 0; i < iters; i++) {
      let r;
      for (;;) { r = tryAcquire(lockDir, { compactEvery: 3, stats, hooks: { beforeLink: jitter, beforePostCheck: jitter } }); if (r.status === 'acquired') break; sleepMs(1); }
