// ---------- driver ----------
function child(roleName, lockDir, work, extra = [], env = {}) {
  return spawn(process.execPath, [ME, roleName, lockDir, work, ...extra], { stdio: 'inherit', env: { ...process.env, ...env } });
}
const done = (cp) => new Promise((r) => cp.on('exit', r));
function fresh(name) { const d = fs.mkdtempSync(path.join(HERE, `run-${name}-`)); fs.mkdirSync(path.join(d, 'lock')); return [path.join(d, 'lock'), d]; }
function results(work, prefix) { return fs.readdirSync(work).filter((f) => f.startsWith(prefix) && f.endsWith('.json')).map((f) => JSON.parse(fs.readFileSync(path.join(work, f), 'utf8'))); }

const report = [];
async function caseB1(keepOldEras) {
