  await done(child('cycler', lock, work, ['1'], env));
  const C = child('paused-contender', lock, work, [], env);
  waitFile(path.join(work, 'C-decided'));
  await done(child('cycler', lock, work, ['5'], env)); // compaction moves current era away
  const D = child('holder', lock, work, [], env);
  waitFile(path.join(work, 'D-inside'));
  fs.writeFileSync(path.join(work, 'C-go'), '');
