  await cDone;
  const c = results(work, 'paused-contender')[0];
  const d = JSON.parse(fs.readFileSync(path.join(work, 'D-inside'), 'utf8'));
  fs.writeFileSync(path.join(work, 'D-leave'), ''); await done(D);
  report.push({ case: `B1 paused contender across era compaction, keepOldEras=${keepOldEras}`, C: c, D: d, twoHolders: c.status === 'acquired' });
}
async function caseHolderCompactsThenDies() {
  // Deterministic version of the B1 class for eras: a stale contender read
  // `current` = era0; the holder of era0's max moves the ledger to era1 and
  // dies; a fresh contender D takes epoch 2 in era1; C then links epoch 2 into
  // the now-unreachable era0. Only the post-check stops C.
  const [lock, work] = fresh('compact-die');
  const S = child('sleeper', lock, work); await new Promise((r) => setTimeout(r, 300));
  const m = await import('./era-ledger.mjs');
  const st = m.startTimeOf(S.pid);
  const r = m.tryAcquire(lock, { owner: { pid: S.pid, startTime: st }, compactEvery: 64 }); // epoch 1 in era0, owner = sleeper
  const era0 = r.handle.era;
  const C = child('stale-pointer-contender', lock, work, [], { PROBE_KEEP_OLD_ERAS: '1' });
  waitFile(path.join(work, 'C-read-pointer'));
  // Holder-side compaction (copy + pointer swap), keeping era0 on disk, then the holder dies.
  const era1 = `0000000001-${m.currentBoot()}-feedbeef`;
  fs.mkdirSync(path.join(lock, 'eras', era1, 'gen'), { recursive: true }); fs.mkdirSync(path.join(lock, 'eras', era1, 'rel'));
  fs.copyFileSync(path.join(lock, 'eras', era0, 'gen', '0000000001'), path.join(lock, 'eras', era1, 'gen', '0000000001'));
  fs.writeFileSync(path.join(lock, '.ptr'), JSON.stringify({ era: era1 })); fs.renameSync(path.join(lock, '.ptr'), path.join(lock, 'current'));
