  waitFile(path.join(work, 'D-inside'));
  fs.writeFileSync(path.join(work, 'C-go'), ''); await done(C);
  const c = results(work, 'stale-pointer-contender')[0];
  const d = JSON.parse(fs.readFileSync(path.join(work, 'D-inside'), 'utf8'));
  fs.writeFileSync(path.join(work, 'D-leave'), ''); await done(D);
  report.push({ case: 'holder compacts to era1 then dies; stale contender links into era0 while D holds era1', era0, era1, C: c, D: d, twoHolders: c.status === 'acquired' });
}
async function casePostCheckPause() {
  const [lock, work] = fresh('postcheck');
  const P = child('post-check-paused', lock, work);
  waitFile(path.join(work, 'P-linked'));
  await done(child('try-once', lock, work));
  const other = results(work, 'try-once')[0];
  fs.writeFileSync(path.join(work, 'P-go'), ''); await done(P);
  report.push({ case: 'winner paused between link and post-check; another contender tries', other, P: results(work, 'post-check-paused')[0] });
}
async function caseStress(procs, iters) {
  const [lock, work] = fresh('stress');
  const t0 = Date.now();
  await Promise.all(Array.from({ length: procs }, () => done(child('stress', lock, work, [String(iters)]))));
  const rs = results(work, 'stress');
  const sum = (k) => rs.reduce((a, r) => a + (r[k] || 0), 0);
  const st = (k) => rs.reduce((a, r) => a + (r.stats[k] || 0), 0);
  const eras = fs.readdirSync(path.join(lock, 'eras'));
  report.push({ case: `stress ${procs} procs x ${iters}, compaction every 3, jitter before link and before post-check`, acquired: sum('acquired'), csViolations: sum('violations'), compactions: st('compactions'), linksIntoDeletedOrTakenSlot: st('lostLink'), linksIntoUnreachableEra: st('unreachableLink'), eraGoneRestarts: st('eraGone'), erasLeftOnDisk: eras.length, elapsedMs: Date.now() - t0 });
}
async function caseBootEra() {
  const [lock, work] = fresh('boot');
  const S = child('sleeper', lock, work); await new Promise((r) => setTimeout(r, 300));
  const sleeperPid = S.pid;
  // Owner record from "boot A" naming a LIVE pid (models pid reuse after reboot).
  const r1 = await new Promise((res) => { const cp = spawn(process.execPath, ['-e', `
    import('${path.join(HERE, 'era-ledger.mjs')}').then(m=>{ const fs=require('fs');
      const st=m.startTimeOf(${sleeperPid});
      const r=m.tryAcquire('${lock}',{owner:{pid:${sleeperPid},startTime:st},compactEvery:64});
      fs.writeFileSync('${work}/boot-A.json', JSON.stringify({status:r.status, era:r.handle&&r.handle.era})); });`], { stdio: 'inherit', env: { ...process.env, PROBE_BOOT_ID: 'aaaa' } }); cp.on('exit', res); });
  const sameBoot = await new Promise((res) => { const cp = child('try-once', lock, work, [], { PROBE_BOOT_ID: 'aaaa' }); cp.on('exit', res); });
  const sb = results(work, 'try-once')[0]; for (const f of fs.readdirSync(work)) if (f.startsWith('try-once')) fs.rmSync(path.join(work, f));
