  S.kill('SIGKILL');
  report.push({ case: 'boot era: live-pid owner recorded in boot A; contender in boot A vs boot B', bootA: JSON.parse(fs.readFileSync(path.join(work, 'boot-A.json'), 'utf8')), contenderSameBoot: sb, contenderNewBoot: nb, erasAfterNewBoot: erasAfter });
