if (process.env.PROBE_NO_POSTCHECK === '1') { fs.writeFileSync(path.join(HERE, 'probe-era-ledger-negative-results.json'), JSON.stringify(report, null, 1)); console.log(JSON.stringify(report)); process.exit(0); }
