files.probe-grant-gate.mjs:
// Probe B3: spawn -> bind -> GO handshake for a borrowed lock. The holder
// spawns its child behind a gate (blocked on a pipe), publishes the full
// binding tuple, then sends GO. Holder death before GO => the child sees EOF
// and exits without a side effect. Contrast: the v2 order (child runs at
// once, binding published after). Run: node probe-grant-gate.mjs
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { tryAcquire, release, sleepMs, startTimeOf, currentBoot } from './era-ledger.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(5); } };
const now = () => Number(process.hrtime.bigint() / 1000n); // µs, monotonic, shared clock source on one host
const kill0 = (pid) => { try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; } };
const tupleAlive = (b) => b && kill0(b.pid) && startTimeOf(b.pid) === b.startTime;

/** Receiver check (what a hook does): the borrower must be my direct parent,
 *  by full tuple, not by pid. */
export function acceptBorrow(bound, parentPid, { pidOnly = false } = {}) {
  if (!bound) return false;
  if (bound.pid !== parentPid) return false;
  if (pidOnly) return true;
  return bound.boot === currentBoot() && startTimeOf(parentPid) === bound.startTime;
}

const role = process.argv[2];
if (role) {
  const [lockDir, work] = [process.argv[3], process.argv[4]];
  const sidefx = (tag) => { for (let i = 0; i < 12; i++) { fs.appendFileSync(path.join(work, 'sidefx.log'), `${now()} ${tag}\n`); sleepMs(50); } };
  if (role === 'owner') {
    const mode = process.argv[5]; // gated | ungated
    const r = tryAcquire(lockDir); if (r.status !== 'acquired') throw new Error('owner could not acquire');
    fs.writeFileSync(path.join(work, 'owner-epoch'), String(r.handle.epoch));
    const kid = mode === 'gated'
      ? spawn(process.execPath, [ME, 'gate', lockDir, work], { stdio: ['ignore', 'inherit', 'inherit', 'pipe'] })
      : spawn(process.execPath, [ME, 'ungated-child', lockDir, work], { stdio: 'inherit' });
    // Child pid is known now; the gated child cannot act yet.
    sleepMs(100); // give the scheduler time to run the child before we bind (the B3 window)
    fs.writeFileSync(path.join(work, 'owner-spawned'), String(kid.pid));
    waitFile(path.join(work, 'owner-may-bind'));
    const bound = { epoch: r.handle.epoch, pid: kid.pid, startTime: startTimeOf(kid.pid), boot: currentBoot() };
    fs.writeFileSync(path.join(work, 'bound.json.tmp'), JSON.stringify(bound)); fs.renameSync(path.join(work, 'bound.json.tmp'), path.join(work, 'bound.json'));
    if (mode === 'gated') kid.stdio[3].write('GO\n');
    fs.writeFileSync(path.join(work, 'owner-sent-go'), '');
    waitFile(path.join(work, 'never')); // stays until killed
  }
  if (role === 'gate') {
    const buf = Buffer.alloc(8); let n = 0;
    try { n = fs.readSync(3, buf, 0, 8, null); } catch { n = 0; }
    if (n === 0) { fs.writeFileSync(path.join(work, 'gate-eof-exit'), String(now())); process.exit(125); }
    // A hook-like receiver started by this child checks its parent by tuple.
    const bound = JSON.parse(fs.readFileSync(path.join(work, 'bound.json'), 'utf8'));
    fs.writeFileSync(path.join(work, 'gate-receiver-check.json'), JSON.stringify({ acceptedAsMyChild: acceptBorrow(bound, process.pid) }));
    sidefx('gated-child');
    process.exit(0);
  }
  if (role === 'ungated-child') { sidefx('ungated-child'); process.exit(0); }
  if (role === 'contender') {
    // Generation is free only if owner dead AND bound borrower (if any) dead.
    const extraHeld = () => { try { return tupleAlive(JSON.parse(fs.readFileSync(path.join(work, 'bound.json'), 'utf8'))); } catch { return false; } };
    for (;;) {
      const r = tryAcquire(lockDir, { extraHeld });
      if (r.status === 'acquired') { fs.writeFileSync(path.join(work, 'contender.json'), JSON.stringify({ acquiredAtUs: now(), epoch: r.handle.epoch })); release(r.handle); process.exit(0); }
      sleepMs(20);
    }
  }
}

function fresh(name) { const d = fs.mkdtempSync(path.join(HERE, `run-grant-${name}-`)); fs.mkdirSync(path.join(d, 'lock')); return [path.join(d, 'lock'), d]; }
const done = (cp) => new Promise((r) => cp.on('exit', (code, sig) => r({ code, sig })));
function sideEffects(work) { try { return fs.readFileSync(path.join(work, 'sidefx.log'), 'utf8').trim().split('\n').filter(Boolean).map((l) => Number(l.split(' ')[0])); } catch { return []; } }

async function scenario(name, mode, killAt) {
  const [lock, work] = fresh(name);
  const O = spawn(process.execPath, [ME, 'owner', lock, work, mode], { stdio: 'inherit' });
  waitFile(path.join(work, 'owner-spawned'));
  const childPid = Number(fs.readFileSync(path.join(work, 'owner-spawned'), 'utf8'));
  if (killAt === 'before-bind') { O.kill('SIGKILL'); await done(O); }
  else { fs.writeFileSync(path.join(work, 'owner-may-bind'), ''); waitFile(path.join(work, 'owner-sent-go')); O.kill('SIGKILL'); await done(O); }
  const C = spawn(process.execPath, [ME, 'contender', lock, work], { stdio: 'inherit' });
  await done(C);
  // wait for the child to finish
  for (let i = 0; i < 200 && kill0(childPid); i++) sleepMs(20);
  const c = JSON.parse(fs.readFileSync(path.join(work, 'contender.json'), 'utf8'));
  const fx = sideEffects(work);
  const overlap = fx.filter((t) => t > c.acquiredAtUs).length;
  return {
    case: name, mode, ownerKilled: killAt,
    childExitedOnEofWithoutSideEffect: fs.existsSync(path.join(work, 'gate-eof-exit')),
    sideEffectsTotal: fx.length,
    sideEffectsAfterContenderAcquired: overlap,
    exclusionHeld: overlap === 0,
    receiverCheck: fs.existsSync(path.join(work, 'gate-receiver-check.json')) ? JSON.parse(fs.readFileSync(path.join(work, 'gate-receiver-check.json'), 'utf8')) : null,
  };
}

const report = [];
report.push(await scenario('v2-order-owner-dies-before-bind', 'ungated', 'before-bind'));
report.push(await scenario('v3-gate-owner-dies-before-bind', 'gated', 'before-bind'));
report.push(await scenario('v3-gate-owner-dies-after-go', 'gated', 'after-go'));
// Tuple vs pid-only on a recycled-pid record: parent pid right, startTime wrong.
const fakeBound = { pid: process.pid, startTime: 'not-my-start-time', boot: currentBoot() };
report.push({ case: 'receiver check with matching pid but different start time (models pid reuse)', pidOnlyAccepts: acceptBorrow(fakeBound, process.pid, { pidOnly: true }), fullTupleAccepts: acceptBorrow(fakeBound, process.pid) });
fs.writeFileSync(path.join(HERE, 'probe-grant-gate-results.json'), JSON.stringify(report, null, 1));
for (const r of report) console.log(JSON.stringify(r));

