// Probe F: controller-crash simulation of the v3 run-supervisor protocol.
// Model only (Node), real processes and real kill -9:
//   controller -> spawns supervisor detached (setsid, stdio to files, NO IPC)
//   supervisor -> owns cwd lease + run control (era ledger), home marker,
//                 deadline, heartbeat, receipt; launches worker behind a gate
//   gate       -> waits for GO (pipe), runs worker, kills it if the supervisor dies
//   adopt      -> the upper-layer door (resume / sweep): settles from a receipt,
//                 or marks the attempt abandoned when the supervisor is dead
//   reaper     -> keeps the home iff its owner (the supervisor) is alive|unknown
// Run: node probe-supervisor-crash.mjs
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { tryAcquire, release, sleepMs, startTimeOf, currentBoot, judgeOwner, self } from './era-ledger.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const T = () => Date.now();
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(5); } };
const readJson = (f) => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return null; } };
const publishOnce = (f, obj) => { const tmp = `${f}.tmp-${process.pid}`; fs.writeFileSync(tmp, JSON.stringify(obj)); try { fs.linkSync(tmp, f); return true; } catch (e) { if (e.code !== 'EEXIST') throw e; return false; } finally { fs.unlinkSync(tmp); } };
const kill0 = (pid) => { try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; } };

const role = process.argv[2];
const A = process.argv[3]; // attempt dir
const P = (...x) => path.join(A, ...x);

if (role === 'supervisor') {
  const env = readJson(P('envelope.json'));
  // 1. attempt-scoped locks, owned by the supervisor (not the controller)
  const cwdLease = tryAcquire(P('locks', 'cwd'));
  if (cwdLease.status !== 'acquired') { publishOnce(P('receipt.json'), { outcome: 'not-started', cause: 'cwd-held' }); process.exit(0); }
  const control = tryAcquire(P('locks', 'run-control'));
  // 2. binding = handshake the controller waits for
  publishOnce(P('supervisor-binding.json'), { ...self(), boot: currentBoot(), at: T() });
  // 3. home owned by the supervisor
  fs.mkdirSync(P('home'), { recursive: true });
  fs.writeFileSync(P('home', 'marker.json'), JSON.stringify({ owner: { ...self(), boot: currentBoot() } }));
  // 4. gate + GO
  const gate = spawn(process.execPath, [ME, 'gate', A], { stdio: ['ignore', 'ignore', 'ignore', 'pipe'], detached: true });
  if (env.pauseBeforeGo) { fs.writeFileSync(P('sup-before-go'), ''); waitFile(P('never'), 60000); }
  publishOnce(P('worker-binding.json'), { pid: gate.pid, startTime: startTimeOf(gate.pid), boot: currentBoot() });
  gate.stdio[3].write('GO\n');
  // 5. heartbeat (display only) + deadline
  const hb = setInterval(() => fs.writeFileSync(P('heartbeat'), String(T())), 100);
  let cause = 'exit';
  const deadline = setTimeout(() => { cause = 'deadline'; try { process.kill(-gate.pid, 'SIGTERM'); } catch {} }, env.deadlineMs);
  gate.on('exit', (code, sig) => {
    clearTimeout(deadline); clearInterval(hb);
    publishOnce(P('receipt.json'), { outcome: cause === 'deadline' ? 'timeout' : code === 0 ? 'exited-0' : `exited-${code ?? sig}`, cause, at: T() });
    fs.rmSync(P('home'), { recursive: true, force: true }); // finalize home (credential write-back would run here)
    release(cwdLease.handle); if (control.status === 'acquired') release(control.handle);
    process.exit(0);
  });
}

if (role === 'gate') {
  const buf = Buffer.alloc(8); let n = 0;
  try { n = fs.readSync(3, buf, 0, 8, null); } catch { n = 0; }
  if (n === 0) { fs.writeFileSync(P('gate-eof'), String(T())); process.exit(125); }
  const owner = readJson(P('supervisor-binding.json'));
  const env = readJson(P('envelope.json'));
  const worker = spawn(process.execPath, [ME, 'worker', A, String(env.workMs)], { stdio: 'ignore' });
  const watch = setInterval(() => {
    if (!(kill0(owner.pid) && startTimeOf(owner.pid) === owner.startTime)) { // owner dead => stop the agent
      fs.writeFileSync(P('gate-killed-worker'), String(T())); worker.kill('SIGKILL'); clearInterval(watch); process.exit(137);
    }
  }, 50);
  process.on('SIGTERM', () => { worker.kill('SIGKILL'); process.exit(143); });
  worker.on('exit', (code) => { clearInterval(watch); process.exit(code ?? 1); });
}

if (role === 'worker') {
  const end = T() + Number(process.argv[4]);
  while (T() < end) { fs.appendFileSync(P('worker.log'), `${T()}\n`); sleepMs(50); }
  fs.writeFileSync(P('outbox-result.json'), JSON.stringify({ done: true }));
  process.exit(0);
}

if (role === 'controller') {
  const out = fs.openSync(P('supervisor.out'), 'a');
  const sup = spawn(process.execPath, [ME, 'supervisor', A], { detached: true, stdio: ['ignore', out, out] }); // no IPC
  sup.unref();
  waitFile(P('supervisor-binding.json'));
  fs.writeFileSync(P('controller-saw-binding'), String(T()));
  waitFile(P('receipt.json'), 60000);
  adopt('controller');
  process.exit(0);
}

/** Upper-layer door: settle the attempt from facts, never re-run it. */
function adopt(by) {
  const result = readJson(P('result.json'));
  if (result) return result;
  const sup = readJson(P('supervisor-binding.json'));
  const supState = sup ? judgeOwner(sup) : 'never-started';
  const receipt = readJson(P('receipt.json'));
  if (receipt) { publishOnce(P('result.json'), { state: 'settled', from: 'receipt', receipt, by }); return readJson(P('result.json')); }
  if (supState === 'alive' || supState === 'unknown') return { state: 'running', supervisor: supState };
  // supervisor dead without receipt: make sure the agent is gone, then close the attempt
  const wb = readJson(P('worker-binding.json'));
  if (wb && kill0(wb.pid) && startTimeOf(wb.pid) === wb.startTime) { try { process.kill(-wb.pid, 'SIGKILL'); } catch {} }
  publishOnce(P('result.json'), { state: 'abandoned', cause: 'supervisor-dead-without-receipt', by });
  return readJson(P('result.json'));
}
function reaperDecision() {
  const m = readJson(P('home', 'marker.json'));
  if (!m) return 'no-home';
  const v = judgeOwner(m.owner);
  return v === 'dead' ? 'reap' : 'keep';
}
if (role === 'adopt') { fs.writeFileSync(P(`adopt-${process.argv[4]}.json`), JSON.stringify(adopt(process.argv[4]))); process.exit(0); }

// ---------------- driver ----------------
if (!role) {
  const done = (cp) => new Promise((r) => cp.on('exit', r));
  const mk = (name, envelope) => { const d = fs.mkdtempSync(path.join(HERE, `run-sup-${name}-`)); fs.writeFileSync(path.join(d, 'envelope.json'), JSON.stringify(envelope)); return d; };
  const proc = (r, a, extra = []) => spawn(process.execPath, [ME, r, a, ...extra], { stdio: 'inherit' });
  const lastWorkerWrite = (a) => { try { const l = fs.readFileSync(path.join(a, 'worker.log'), 'utf8').trim().split('\n'); return Number(l[l.length - 1]); } catch { return null; } };
  const supPid = (a) => readJson(path.join(a, 'supervisor-binding.json'))?.pid;
  const report = [];

  { // A: controller SIGKILL mid-run; supervisor finishes; adopt settles
    const a = mk('A', { workMs: 1500, deadlineMs: 5000 });
    const c = proc('controller', a); waitFile(path.join(a, 'controller-saw-binding'));
    sleepMs(200); c.kill('SIGKILL'); await done(c);
    const midRun = { reaper: (() => { const A0 = a; return (function () { const m = readJson(path.join(A0, 'home', 'marker.json')); return m ? (judgeOwner(m.owner) === 'dead' ? 'reap' : 'keep') : 'no-home'; })(); })(),
      cwdLeaseForOthers: tryAcquire(path.join(a, 'locks', 'cwd')).status };
    waitFile(path.join(a, 'receipt.json'));
    await done(proc('adopt', a, ['resume']));
    report.push({ case: 'A controller SIGKILL mid-run', midRun, receipt: readJson(path.join(a, 'receipt.json')), adopted: readJson(path.join(a, 'adopt-resume.json')), workerFinished: fs.existsSync(path.join(a, 'outbox-result.json')), homeAfter: fs.existsSync(path.join(a, 'home')) ? 'present' : 'finalized' });
  }
  { // B: controller SIGKILL; deadline shorter than the work
    const a = mk('B', { workMs: 3000, deadlineMs: 1000 });
    const c = proc('controller', a); waitFile(path.join(a, 'controller-saw-binding'));
    const t0 = readJson(path.join(a, 'supervisor-binding.json')).at;
    c.kill('SIGKILL'); await done(c);
    waitFile(path.join(a, 'receipt.json'));
    sleepMs(200);
    await done(proc('adopt', a, ['resume']));
    report.push({ case: 'B controller SIGKILL, deadline 1000 ms < work 3000 ms', receipt: readJson(path.join(a, 'receipt.json')), workerLastWriteAfterStartMs: lastWorkerWrite(a) - t0, workerFinished: fs.existsSync(path.join(a, 'outbox-result.json')), adopted: readJson(path.join(a, 'adopt-resume.json')) });
  }
  { // C: supervisor SIGKILL mid-run; gate stops the worker; adopt marks abandoned
    const a = mk('C', { workMs: 4000, deadlineMs: 10000 });
    const c = proc('controller', a); waitFile(path.join(a, 'controller-saw-binding'));
    c.kill('SIGKILL'); await done(c);
    sleepMs(500);
    const killedAt = T(); process.kill(supPid(a), 'SIGKILL');
    sleepMs(400);
    const reaper = (() => { const m = readJson(path.join(a, 'home', 'marker.json')); return m ? (judgeOwner(m.owner) === 'dead' ? 'reap' : 'keep') : 'no-home'; })();
    await done(proc('adopt', a, ['sweep']));
    const lease = tryAcquire(path.join(a, 'locks', 'cwd'));
    report.push({ case: 'C supervisor SIGKILL mid-run (controller already dead)', workerStoppedWithinMs: lastWorkerWrite(a) - killedAt, gateKilledWorker: fs.existsSync(path.join(a, 'gate-killed-worker')), reaperDecision: reaper, adopted: readJson(path.join(a, 'adopt-sweep.json')), cwdLeaseNow: lease.status });
  }
  { // D: resume while the supervisor is alive must not launch a second worker
    const a = mk('D', { workMs: 1500, deadlineMs: 5000 });
    const c = proc('controller', a); waitFile(path.join(a, 'controller-saw-binding'));
    c.kill('SIGKILL'); await done(c);
    await done(proc('adopt', a, ['resume-early']));
    const secondLaunch = tryAcquire(path.join(a, 'locks', 'cwd'));
    waitFile(path.join(a, 'receipt.json'));
    await done(proc('adopt', a, ['resume-late']));
    report.push({ case: 'D resume while supervisor alive, then after receipt', early: readJson(path.join(a, 'adopt-resume-early.json')), secondLaunchCwdLease: secondLaunch.status, late: readJson(path.join(a, 'adopt-resume-late.json')) });
  }
  { // E: supervisor SIGKILL after spawning the gate, before GO
    const a = mk('E', { workMs: 1500, deadlineMs: 5000, pauseBeforeGo: true });
    const c = proc('controller', a); waitFile(path.join(a, 'sup-before-go'));
    process.kill(supPid(a), 'SIGKILL'); c.kill('SIGKILL'); await done(c);
    sleepMs(300);
    await done(proc('adopt', a, ['sweep']));
    report.push({ case: 'E supervisor SIGKILL between gate spawn and GO', gateExitedOnEof: fs.existsSync(path.join(a, 'gate-eof')), workerEverRan: fs.existsSync(path.join(a, 'worker.log')), adopted: readJson(path.join(a, 'adopt-sweep.json')) });
  }
  fs.writeFileSync(path.join(HERE, 'probe-supervisor-crash-results.json'), JSON.stringify(report, null, 1));
  for (const r of report) console.log(JSON.stringify(r));
}
